await js(`document.querySelector('[data-expand]').click()`); ok('expander closes again', await js(`document.querySelectorAll('.feed [data-nzb]').length`) === collapsed);
await js(`[...document.querySelectorAll('[data-expand]')].length`);
ok('expanding everything on the page gives exactly 50', await js(`(()=>{const rs=REL.filter(match).sort((a,b)=>b.t-a.t).slice(0,50);let d='',i=0;while(i<rs.length){let j=i;while(j<rs.length&&rs[j].v===rs[i].v&&dayKey(rs[j].t)===dayKey(rs[i].t))j++;state.expanded.add(rs[i].v+'|'+dayKey(rs[i].t)+'|'+rs[i].id);i=j;}route();const n=document.querySelectorAll('.feed [data-nzb]').length;state.expanded.clear();route();return n;})()`) === 50);
ok('only the release name is bold in a row', await js(`(()=>{const tr=document.querySelector('.feed [data-nzb]').closest('tr');const heavy=[...tr.querySelectorAll('*')].filter(e=>[...e.childNodes].some(n=>n.nodeType===3&&n.textContent.trim())&&+getComputedStyle(e).fontWeight>=600);return heavy.length===1&&heavy[0].classList.contains('rname');})()`));
ok('resolution chips form a clean column (same left edge, same width, same height)', await js(`(()=>{const b=[...document.querySelectorAll('.feed .res')].map(e=>e.getBoundingClientRect());return b.length>5&&b.every(r=>Math.abs(r.left-b[0].left)<0.5&&Math.abs(r.width-b[0].width)<0.5&&Math.abs(r.height-b[0].height)<0.5);})()`));
ok('each resolution has its own colour', await js(`(()=>{state.per=9000;route();const seen={};document.querySelectorAll('.feed .res').forEach(e=>{seen[e.textContent]=getComputedStyle(e).backgroundColor;});state.per=50;route();const v=Object.values(seen);window.__res=seen;return Object.keys(seen).length>=4&&new Set(v).size===v.length;})()`), JSON.stringify(await js(`Object.keys(window.__res||{})`)));
ok('completion chips are coloured by his bands: 95+ green, 75-94 orange, under 75 red; none at 100%', await js(`(()=>{state.per=9000;route();let n={ok:0,mid:0,low:0},bad=0;document.querySelectorAll('.feed [data-nzb]').forEach(b=>{const r=BYID[b.dataset.nzb],pc=Math.floor(r.comp),chip=b.closest('tr').querySelector('.rc.comp');if(pc>=100){if(chip)bad++;return;}const want=pc>=95?'c-ok':pc>=75?'c-mid':'c-low';if(!chip||!chip.classList.contains(want))bad++;n[want.slice(2)]++;});state.per=50;route();window.__comp=n;return bad===0&&n.ok>0&&n.mid>0&&n.low>0;})()`), JSON.stringify(await js(`window.__comp`)));
ok('NFO chip is the letters NFO with no icon; Preview and Sample are words', await js(`(()=>{state.per=9000;route();const n=document.querySelector('.feed [data-nfo]'),p=document.querySelector('.feed [data-img][data-kind=preview]');const r=n.textContent==='NFO'&&!n.querySelector('svg')&&p.textContent==='Preview'&&!p.querySelector('svg');state.per=50;route();return r;})()`));
ok('every chip kind has its own colour, all readable (4.5:1), both themes', await js(`(()=>{const lum=c=>{const m=c.match(/[0-9.]+/g).map(Number);const f=v=>{v/=255;return v<=0.03928?v/12.92:Math.pow((v+0.055)/1.055,2.4);};return 0.2126*f(m[0])+0.7152*f(m[1])+0.0722*f(m[2]);};const toRgb=v=>{const d=document.createElement('canvas').getContext('2d');d.fillStyle=v;d.fillRect(0,0,1,1);const p=d.getImageData(0,0,1,1).data;return 'rgb('+p[0]+','+p[1]+','+p[2]+')';};const out=[];let distinct=true;for(const theme of ['dark','light']){document.documentElement.dataset.theme=theme;const cs=getComputedStyle(document.documentElement);const bgs=[];for(const k of ['k-mi','k-nfo','k-pv','k-sm','c-ok','c-mid','c-low']){const bg=toRgb(cs.getPropertyValue('--'+k+'-bg')),fg=toRgb(cs.getPropertyValue('--'+k+'-fg'));const a=lum(bg),b=lum(fg);out.push((Math.max(a,b)+0.05)/(Math.min(a,b)+0.05));bgs.push(bg+fg);}if(new Set(bgs).size!==7)distinct=false;}document.documentElement.dataset.theme='dark';window.__cr2=out.map(x=>+x.toFixed(1));return distinct&&out.every(x=>x>=4.5);})()`), JSON.stringify(await js(`window.__cr2`)));
ok('the three completion colours are different and readable (4.5:1)', await js(`(()=>{const lum=c=>{const m=c.match(/[0-9.]+/g).map(Number);const f=v=>{v/=255;return v<=0.03928?v/12.92:Math.pow((v+0.055)/1.055,2.4);};return 0.2126*f(m[0])+0.7152*f(m[1])+0.0722*f(m[2]);};const toRgb=(v)=>{const d=document.createElement('canvas').getContext('2d');d.fillStyle=v;d.fillRect(0,0,1,1);const p=d.getImageData(0,0,1,1).data;return 'rgb('+p[0]+','+p[1]+','+p[2]+')';};const out=[];for(const theme of ['dark','light']){document.documentElement.dataset.theme=theme;const cs=getComputedStyle(document.documentElement);const bgs=[];for(const k of ['ok','mid','low']){const bg=toRgb(cs.getPropertyValue('--c-'+k+'-bg')),fg=toRgb(cs.getPropertyValue('--c-'+k+'-fg'));const a=lum(bg),b=lum(fg);out.push((Math.max(a,b)+0.05)/(Math.min(a,b)+0.05));bgs.push(bg);}if(new Set(bgs).size!==3)out.push(0);}document.documentElement.dataset.theme='dark';window.__cr=out.map(x=>+x.toFixed(1));return out.every(x=>x>=4.5);})()`), JSON.stringify(await js(`window.__cr`)));
